#include <iostream>
using namespace std;
int binarySearch(int arr[], int size, int target) { int low = 0, high = size - 1; while (low <= high) { int mid = (low + high) / 2; if (arr[mid] == target) return mid; else if (arr[mid] < target) low = mid + 1; else high = mid - 1; } return -1; } int main() { int n, target; cout << "Size (sorted): "; cin >> n; int arr[n]; cout << "Enter " << n << " sorted elements:\n"; for (int i = 0; i < n; i++) { cout << "Element " << i + 1 << ": "; cin >> arr[i]; } cout << "Search: "; cin >> target; int result = binarySearch(arr, n, target); if (result != -1) cout << "Found at: " << result << endl; else cout << "Not found!" << endl; return 0; }